<?php
namespace Tests\Feature;
use App\Models\Admin;use App\Models\RolePermission;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Route;use Tests\TestCase;
class RbacTest extends TestCase { use RefreshDatabase;
 public function test_admin_permissions_are_live_and_homepage_is_super_admin_only():void { $admin=Admin::create(['name'=>'Admin','email'=>'rbac-admin@example.test','password'=>'password123','role'=>'admin','is_active'=>true]); $token=$admin->createToken('test',['admin'])->plainTextToken; $this->withToken($token)->getJson('/api/admin/homepage/banners')->assertForbidden()->assertJsonPath('permission','storefront.edit'); $this->withToken($token)->getJson('/api/admin/dashboard')->assertOk(); RolePermission::where('role','admin')->update(['permissions'=>[]]); \Illuminate\Support\Facades\Cache::forget('rbac.admin'); $this->withToken($token)->getJson('/api/admin/dashboard')->assertForbidden(); }
 public function test_every_console_group_route_has_permission_or_is_self_service():void { $self=['api/admin/login','api/admin/forgot-password','api/admin/reset-password','api/admin/check-reset-code','api/admin/me','api/admin/logout','api/sellers/login','api/sellers/onboard','api/sellers/forgot-password','api/sellers/reset-password','api/sellers/check-reset-code','api/sellers/me','api/sellers/logout','api/seller/staff/me']; foreach(Route::getRoutes() as $route){$uri=$route->uri();if(!preg_match('~^api/(admin|seller)/~',$uri)||in_array($uri,$self,true)||str_contains($uri,'/me/'))continue;$has=collect($route->gatherMiddleware())->contains(fn($m)=>str_contains($m,'PermissionMiddleware') || str_starts_with($m,'perm:'));$this->assertTrue($has,"{$uri} has no perm middleware");} }
}
